    rows.append(expo(259,'Games & Comic Con Dzaïr · 2027 date conflict','DZA',GCC,city='Palais de la Culture · Moufdi Zakaria · Algiers',themes=['games','art','technology'],period=T('Объявлен 2027; футер 2–4 апреля содержит дни недели 2026. Точные дни до подтверждения не включены в календарь.', 'Anunciado 2027; pie del 2–4 de abril contiene días de semana de 2026. Días exactos sin incluir en calendario hasta confirmar.'),adult_entry=T('На странице: 1000 DA / день, 2500 DA / 3 дня; студентам / младше 18 — 500 DA / день с подтверждением. Cosplay / e-sports pass 1500 DA только участникам конкурсов. Применимость к нужному выпуску и возрастам 6 / 9 уточнить.', 'Página: 1000 DA / día, 2500 DA / 3 días; estudiantes / menores de 18 — 500 DA / día con justificante. Pass cosplay / e-sports 1500 DA solo concursantes. Confirmar aplicación a edición elegida y edades de 6 / 9.'),note=T('Gaming, free-to-play и indie-разработчики подтверждены как направления. Заголовки смешивают 2026 и 2027; форма участника ещё недоступна. Нельзя обещать ребёнку турнирное место или поездку на EVO по прошлым новостям.', 'Gaming, free-to-play y desarrolladores indie confirmados como áreas. Cabeceras mezclan 2026 y 2027; formulario participante aún no disponible. Sin prometer plaza infantil en torneo o viaje a EVO por noticias pasadas.')))
