        if not any(r['entity_id']==eid and r['year']==2026 for r in h['results']):h['results'].append(dict(id='H'+str(max(int(r['id'][1:])for r in h['results'])+1).zfill(3),entity_id=eid,year=2026,league='WRO',category='Future Innovators · national overall',stage='National Final · Mozambique',award=award,level='national_other',source=MOZ+'events.html',provenance='organizer_report',team=name,team_id=None,note=note,checked=CHECKED))
